1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	let pendingMessages = new Map();
24	let controlWs = null;
25	let reconnectTimer = null;
26	let reconnectAttempts = 0;
27	
28	// ===== sessionStorage：刷新后记住连接状态 =====
29	const SS_PREFIX = 'lanchat_conn_';
30	
31	function markConnected(uuid) {
32	    try { sessionStorage.setItem(SS_PREFIX + uuid, '1'); } catch (e) { /* ignore */ }
33	}
34	
35	function markDisconnected(uuid) {
36	    try { sessionStorage.removeItem(SS_PREFIX + uuid); } catch (e) { /* ignore */ }
37	}
38	
39	function getStoredConnectedPeers() {
40	    const peers = [];
41	    try {
42	        for (let i = 0; i < sessionStorage.length; i++) {
43	            const key = sessionStorage.key(i);
44	            if (key && key.startsWith(SS_PREFIX)) {
45	                peers.push(key.slice(SS_PREFIX.length));
46	            }
47	        }
48	    } catch (e) { /* ignore */ }
49	    return peers;
50	}
51	
52	// 文件传输状态
53	let pendingFileTransfers = {};
54	
55	// ===== DOM 引用 =====
56	const $ = (id) => document.getElementById(id);
57	const onlineList = $('online-list');
58	const onlineCount = $('online-count');
59	const pendingList = $('pending-list');
60	const pendingCount = $('pending-count');
61	const panelPending = $('panel-pending');
62	const contactsList = $('contacts-list');
63	const contactsCount = $('contacts-count');
64	const chatPlaceholder = $('chat-placeholder');
65	const chatContainer = $('chat-container');
66	const chatPeerName = $('chat-peer-name');
67	const chatPeerStatus = $('chat-peer-status');
68	const chatConnectBar = $('chat-connect-bar');
69	const btnChatConnect = $('btn-chat-connect');
70	const chatMessages = $('chat-messages');
71	const msgInput = $('msg-input');
72	const btnSend = $('btn-send');
73	const btnSendFile = $('btn-send-file');
74	const fileInput = $('file-input');
75	const btnCloseChat = $('btn-close-chat');
76	const btnDeleteContact = $('btn-delete-contact');
77	const btnDisconnect = $('btn-disconnect');
78	const btnScan = $('btn-scan');
79	const btnEditName = $('btn-edit-name');
80	const modalOverlay = $('modal-overlay');
81	const modalNameInput = $('modal-name-input');
82	const fileModalOverlay = $('file-modal-overlay');
83	const fileModalTitle = $('file-modal-title');
84	const fileModalBody = $('file-modal-body');
85	const fileModalButtons = $('file-modal-buttons');
86	
87	// ===== 初始化 =====
88	async function init() {
89	    await connectControl();
90	    bindEvents();
91	    startPolling();
92	}
93	
94	/** 连接控制 WebSocket */
95	async function connectControl() {
96	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
97	    const url = `${protocol}//${location.host}/ws/control`;
98	
99	    return new Promise((resolve) => {
100	        controlWs = new WebSocket(url);
101	
102	        controlWs.onopen = () => {
103	            reconnectAttempts = 0;
104	            console.log('[Control] 已连接');
105	        };
106	
107	        controlWs.onmessage = (e) => {
108	            const msg = JSON.parse(e.data);
109	            handleControlMessage(msg);
110	            if (msg.type === 'init') resolve();
111	        };
112	
113	        controlWs.onclose = () => {
114	            console.log('[Control] 断开，尝试重连...');
115	            scheduleReconnect();
116	        };
117	
118	        controlWs.onerror = () => {};
119	    });
120	}
121	
122	/** 控制 WS 断开后指数退避重连 */
123	function scheduleReconnect() {
124	    if (reconnectTimer) return;
125	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
126	    const jitter = delay * (0.8 + Math.random() * 0.4);
127	    reconnectAttempts++;
128	    reconnectTimer = setTimeout(async () => {
129	        reconnectTimer = null;
130	        await connectControl();
131	    }, jitter);
132	}
133	
134	// ===== 事件绑定 =====
135	function bindEvents() {
136	    btnScan.addEventListener('click', () => fetchPeers());
137	    btnEditName.addEventListener('click', showEditNameModal);
138	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
139	    $('btn-modal-save').addEventListener('click', saveName);
140	    modalNameInput.addEventListener('keydown', (e) => {
141	        if (e.key === 'Enter') saveName();
142	    });
143	    btnSend.addEventListener('click', sendCurrentMessage);
144	    msgInput.addEventListener('keydown', (e) => {
145	        if (e.key === 'Enter') sendCurrentMessage();
146	    });
147	    btnSendFile.addEventListener('click', () => fileInput.click());
148	    fileInput.addEventListener('change', onFileSelected);
149	    btnCloseChat.addEventListener('click', closeCurrentChat);
150	    btnDisconnect.addEventListener('click', disconnectCurrentChat);
151	    btnChatConnect.addEventListener('click', () => {
152	        if (!currentChat) return;
153	        const peer = onlinePeers.get(currentChat) || contacts.get(currentChat);
154	        if (peer) connectToPeer(currentChat, peer.name, peer.ip);
155	    });
156	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
157	
158	    // 手动连接：toggle 展开/收起
159	    const btnManualConnect = $('btn-manual-connect');
160	    const manualIpInput = $('manual-ip-input');
161	
162	    btnManualConnect.addEventListener('click', () => {
163	        const raw = manualIpInput.value.trim();
164	        if (!raw) return;
165	        let [ip, port] = raw.split(':');
166	        port = parseInt(port) || 50002;
167	        connectByIp(ip, port);
168	        manualIpInput.value = '';
169	        toggleManualConnect(); // 收起
170	    });
171	    manualIpInput.addEventListener('keydown', (e) => {
172	        if (e.key === 'Enter') btnManualConnect.click();
173	    });
174	
175	    // 文件续传按钮（事件委托）
176	    chatMessages.addEventListener('click', (e) => {
177	        const btn = e.target.closest('.btn-retry-file');
178	        if (btn) {
179	            const transferId = btn.dataset.transferId;
180	            if (transferId) retryFileTransfer(transferId);
181	        }
182	    });
183	}
184	
185	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
186	function toggleManualConnect() {
187	    const row = $('manual-connect-row');
188	    const btn = $('btn-toggle-manual');
189	    if (!row || !btn) return;
190	    const visible = row.style.display !== 'none';
191	    row.style.display = visible ? 'none' : '';
192	    btn.textContent = visible ? '➕' : '✖';
193	    if (!visible) $('manual-ip-input').focus();
194	}
195	
196	// ===== 定时轮询 =====
197	function startPolling() {
198	    setInterval(fetchPeers, 3000);
199	    setInterval(fetchContacts, 5000);
200	    fetchPeers();
201	    fetchContacts();
202	}
203	
204	async function fetchPeers() {
205	    try {
206	        const resp = await fetch('/api/peers');
207	        const peers = await resp.json();
208	        updateOnlinePeers(peers);
209	    } catch (e) { /* ignore */ }
210	}
211	
212	async function fetchContacts() {
213	    try {
214	        const resp = await fetch('/api/contacts');
215	        const list = await resp.json();
216	        updateContacts(list);
217	    } catch (e) { /* ignore */ }
218	}
219	
220	// ===== 控制消息处理 =====
221	function handleControlMessage(msg) {
222	    const handlers = {
223	        init: handleInit,
224	        peer_online: handlePeerOnline,
225	        peer_offline: handlePeerOffline,
226	        incoming_connection: handleIncomingConnection,
227	        pending_update: handlePendingUpdate,
228	        connection_established: handleConnectionEstablished,
229	        peer_disconnected: handlePeerDisconnected,
230	        disconnected: handleDisconnected,
231	        chat_message: handleIncomingMessage,
232	        message_ack: handleMessageAck,
233	        send_failed: handleSendFailed,
234	        incoming_file_request: handleIncomingFileRequest,
235	        file_request_response: handleFileRequestResponseFromControl,
236	        forward_file_response: handleForwardFileResponse,
237	        transfer_progress: handleTransferProgress,
238	        transfer_complete: handleTransferComplete,
239	        transfer_cancelled: handleTransferCancelled,
240	        transfer_resumed: handleTransferResumed,
241	    };
242	    const handler = handlers[msg.type];
243	    if (handler) handler(msg);
244	}
245	
246	function handleInit(msg) {
247	    myInfo = msg;
248	    $('my-name-label').textContent = msg.name;
249	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
250	    $('my-network-label').textContent = `网段: ${msg.network}`;
251	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
252	
253	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
254	    if (msg.online_peers && msg.online_peers.length > 0) {
255	        updateOnlinePeers(msg.online_peers);
256	    }
257	
258	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
259	    if (msg.contacts && msg.contacts.length > 0) {
260	        updateContacts(msg.contacts);
261	    }
262	
263	    // 步骤3：自动重连刷新前已建立的连接（双重来源）
264	    //   来源A — sessionStorage：本浏览器侧记忆，刷新不丢失
265	    //   来源B — active_peers：后端记录，对端浏览器仍连着本后端的 chat WS
266	    const toReconnect = new Set();
267	    for (const uuid of getStoredConnectedPeers()) {
268	        toReconnect.add(uuid);
269	    }
270	    if (msg.active_peers && msg.active_peers.length > 0) {
271	        for (const uuid of msg.active_peers) {
272	            toReconnect.add(uuid);
273	        }
274	    }
275	    for (const peerUuid of toReconnect) {
276	        autoReconnect(peerUuid);
277	    }
278	}
279	
280	function handlePeerOnline(msg) {
281	    // 过滤自己
282	    if (msg.uuid === myInfo.uuid) return;
283	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
284	    // 如果历史联系人里有，同步更新在线状态、昵称和 IP（对方可能换了 IP 或改了昵称）
285	    if (contacts.has(msg.uuid)) {
286	        contacts.get(msg.uuid).status = 'online';
287	        if (msg.name) contacts.get(msg.uuid).name = msg.name;
288	        if (msg.ip) contacts.get(msg.uuid).ip = msg.ip;
289	    }
290	    renderOnlineList();
291	    renderContactsList();
292	    updateChatHeaderStatus();
293	}
294	
295	function handlePeerOffline(msg) {
296	    onlinePeers.delete(msg.uuid);
297	    if (contacts.has(msg.uuid)) {
298	        contacts.get(msg.uuid).status = 'offline';
299	    }
300	    // 对应聊天 WS 断开
301	    const ws = activeChats.get(msg.uuid);
302	    if (ws) {
303	        ws.close();
304	        activeChats.delete(msg.uuid);
305	    }
306	    renderOnlineList();
307	    renderContactsList();
308	    updateChatHeaderStatus();
309	    addSystemMessage(msg.uuid, `${msg.name} 已下线`);
310	}
311	
312	function handleIncomingConnection(msg) {
313	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
314	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
315	    renderPendingList();
316	}
317	
318	function handlePendingUpdate(msg) {
319	    // count 可能在 pending 列表被其他地方修改后推送
320	    if (msg.count === 0) pendingRequests.clear();
321	}
322	
323	function handleConnectionEstablished(msg) {
324	    pendingRequests.delete(msg.uuid);
325	    connectedPeers.add(msg.uuid);  // 接收方也标记为已连接
326	    markConnected(msg.uuid);
327	    // 只在 contacts 中不存在时才新建，否则保留已有消息（避免覆盖聊天记录）
328	    if (!contacts.has(msg.uuid)) {
329	        contacts.set(msg.uuid, {
330	            name: msg.name,
331	            ip: msg.ip,
332	            status: 'online',
333	            messages: [],
334	        });
335	    } else {
336	        const c = contacts.get(msg.uuid);
337	        c.name = msg.name;
338	        c.ip = msg.ip;
339	        c.status = 'online';
340	    }
341	    renderPendingList();
342	    renderOnlineList();
343	    renderContactsList();
344	    updateChatHeaderStatus();
345	    // 如果正在等对方的确认（主动发起方），打开聊天
346	    if (currentChat === msg.uuid || !currentChat) {
347	        openChat(msg.uuid);
348	    }
349	}
350	
351	function handlePeerDisconnected(msg) {
352	    activeChats.delete(msg.uuid);
353	    connectedPeers.delete(msg.uuid);
354	    markDisconnected(msg.uuid);
355	    pendingRequests.delete(msg.uuid);
356	    // 中止与该对端的所有进行中文件上传
357	    abortTransfersForPeer(msg.uuid);
358	    renderPendingList();
359	    renderOnlineList();
360	    renderContactsList();
361	    if (currentChat === msg.uuid) {
362	        updateChatHeaderStatus();
363	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
364	    }
365	}
366	
367	/** 自己主动断开后的确认回调（后端关闭对端 WS 后返回） */
368	function handleDisconnected(msg) {
369	    activeChats.delete(msg.uuid);
370	    connectedPeers.delete(msg.uuid);
371	    markDisconnected(msg.uuid);
372	    renderOnlineList();
373	    renderContactsList();
374	    if (currentChat === msg.uuid) {
375	        updateChatHeaderStatus();
376	        addSystemMessage(msg.uuid, '你已断开连接');
377	    }
378	}
379	
380	function handleIncomingMessage(msg) {
381	    const uuid = msg.from;
382	    // 保存消息到联系人内存
383	    if (!contacts.has(uuid)) {
384	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
385	    }
386	    const contact = contacts.get(uuid);
387	    contact.messages.push({
388	        from: uuid,
389	        content: msg.content,
390	        msg_id: msg.msg_id,
391	        timestamp: msg.timestamp,
392	    });
393	    // 立即通知后端持久化到 contacts.json（与后端 _relay_from_peer 形成双保险，
394	    // storage.append_message 内部有 msg_id 去重，重复调用安全）
395	    controlWs.send(JSON.stringify({
396	        type: 'save_message',
397	        peer_uuid: uuid,
398	        sender: uuid,
399	        content: msg.content,
400	        msg_id: msg.msg_id,
401	    }));
402	    if (currentChat === uuid) {
403	        renderMessages(uuid);
404	    }
405	    // 当前没有聊天窗口时，自动打开
406	    if (!currentChat) {
407	        openChat(uuid);
408	    }
409	    renderContactsList();
410	}
411	
412	function handleMessageAck(msg) {
413	    pendingMessages.delete(msg.msg_id);
414	    if (currentChat) renderMessages(currentChat);
415	}
416	
417	function handleSendFailed(msg) {
418	    // 标记消息发送失败
419	    const pending = pendingMessages.get(msg.msg_id);
420	    if (pending) {
421	        pending.status = 'failed';
422	        pendingMessages.set(msg.msg_id, pending);
423	    }
424	    if (currentChat) renderMessages(currentChat);
425	}
426	
427	// ===== 文件传输消息处理 =====
428	
429	function handleIncomingFileRequest(msg) {
430	    // 续传：自动接受，不弹窗
431	    if (msg.resume) {
432	        autoAcceptResumeTransfer(msg);
433	        return;
434	    }
435	    showFileRequestModal(msg);
436	}
437	
438	/** 续传自动接受（不弹窗），更新已有文件气泡或插入新气泡 */
439	function autoAcceptResumeTransfer(msg) {
440	    // 发送接受响应
441	    controlWs.send(JSON.stringify({
442	        type: 'file_response',
443	        transfer_id: msg.transfer_id,
444	        accepted: true,
445	    }));
446	
447	    const uuid = msg.from_uuid;
448	    if (!contacts.has(uuid)) {
449	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
450	    }
451	    const contact = contacts.get(uuid);
452	    const msgId = 'f_' + msg.transfer_id;
453	    const existingIdx = contact.messages.findIndex(m => m.msg_id === msgId);
454	    if (existingIdx >= 0) {
455	        // 续传：更新已有消息
456	        contact.messages[existingIdx].status = 'downloading';
457	        contact.messages[existingIdx].progress = 0;
458	        saveFileMessage(uuid, contact.messages[existingIdx]);
459	    } else {
460	        const fileMsg = {
461	            from: uuid,
462	            type: 'file',
463	            msg_id: msgId,
464	            timestamp: new Date().toISOString(),
465	            file_name: msg.file_name,
466	            file_size: msg.file_size,
467	            transfer_id: msg.transfer_id,
468	            direction: 'receive',
469	            status: 'downloading',
470	            progress: 0,
471	        };
472	        contact.messages.push(fileMsg);
473	        saveFileMessage(uuid, fileMsg);
474	    }
475	    if (currentChat === uuid) {
476	        renderMessages(uuid);
477	    } else {
478	        openChat(uuid);
479	    }
480	}
481	
482	/**
483	 * 处理来自控制 WS 的文件请求响应（通过后端 _relay_from_peer 转发的）。
484	 * 与来自聊天 WS 直连的响应统一走 handleFileRequestResponse。
485	 */
486	function handleFileRequestResponseFromControl(msg) {
487	    handleFileRequestResponse(msg);
488	}
489	
490	/**
491	 * 统一处理文件请求响应。
492	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
493	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
494	 */
495	function handleFileRequestResponse(msg) {
496	    const transferId = msg.transfer_id;
497	    const t = pendingFileTransfers[transferId];
498	    if (!t) return; // 不是我们的传输
499	
500	    if (msg.accepted) {
501	        if (t.started) return; // 已启动，幂等
502	        t.started = true;
503	        startChunkUpload(transferId);
504	    } else {
505	        // 对方拒绝
506	        delete pendingFileTransfers[transferId];
507	        const fileMsg = findFileMsgByTransferId(transferId);
508	        if (fileMsg) {
509	            fileMsg.status = 'failed';
510	            // 通过 transferId 找到对应的联系人 uuid
511	            saveFileMessage(t.uuid, fileMsg);
512	            if (currentChat) renderMessages(currentChat);
513	        }
514	        showToast('对方拒绝了文件传输');
515	    }
516	}
517	
518	function handleTransferProgress(msg) {
519	    // 接收方：更新文件消息进度
520	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
521	    if (fileMsg && msg.total_bytes > 0) {
522	        fileMsg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
523	        if (currentChat) renderMessages(currentChat);
524	    }
525	}
526	
527	function handleTransferComplete(msg) {
528	    // 接收方：传输完成
529	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
530	    if (fileMsg) {
531	        fileMsg.status = msg.verified ? 'complete' : 'failed';
532	        fileMsg.progress = 100;
533	        saveFileMessage(currentChat, fileMsg);
534	        if (currentChat) renderMessages(currentChat);
535	    }
536	    if (msg.verified) {
537	        showToast(`文件接收完成: ${msg.file_name}`);
538	    } else {
539	        showToast(`文件校验失败: ${msg.file_name}`);
540	    }
541	}
542	
543	function handleTransferCancelled(msg) {
544	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
545	    if (fileMsg) {
546	        fileMsg.status = 'cancelled';
547	        saveFileMessage(currentChat, fileMsg);
548	        if (currentChat) renderMessages(currentChat);
549	    }
550	    // 清理上传方状态
551	    if (pendingFileTransfers[msg.transfer_id]) {
552	        delete pendingFileTransfers[msg.transfer_id];
553	    }
554	    showToast('文件传输已取消');
555	}
556	
557	function handleTransferResumed(msg) {
558	    // 续传恢复通知 — 不做额外弹窗，进度条会在 transfer_progress 中更新
559	    const fileMsg = findFileMsgByTransferId(msg.transfer_id);
560	    if (fileMsg) {
561	        fileMsg.status = 'downloading';
562	        if (currentChat) renderMessages(currentChat);
563	    }
564	}
565	
566	/**
567	 * 当后端无法直接发送 file_response 给发送方时（发送方是被动接收方，无 incoming WS），
568	 * 后端通知本浏览器通过本方的 chat WS 转发响应给对端后端。
569	 */
570	function handleForwardFileResponse(msg) {
571	    const chatWs = activeChats.get(msg.to_uuid);
572	    if (chatWs && chatWs.readyState === WebSocket.OPEN) {
573	        chatWs.send(JSON.stringify({
574	            type: 'file_response',
575	            transfer_id: msg.transfer_id,
576	            accepted: msg.accepted,
577	        }));
578	    }
579	}
580	
581	// ===== 在线列表渲染 =====
582	function updateOnlinePeers(peers) {
