810	        myInfo.token = me.token;
811	    } catch (e) { /* 刷新失败则用现有 token */ }
812	
813	    try {
814	        const wsUrl = `ws://${ip}:${wsPort}/ws/chat`;
815	        const ws = new WebSocket(wsUrl);
816	
817	        ws.onopen = () => {
818	            ws.send(JSON.stringify({
819	                type: 'connect_request',
820	                uuid: myInfo.uuid,
821	                name: myInfo.name,
822	                token: myInfo.token,
823	                ip: myInfo.ip,
824	                ws_port: myInfo.ws_port,
