888	
889	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
890	    try {
891	        const resp = await fetch('/api/me');
892	        const me = await resp.json();
893	        myInfo.token = me.token;
894	    } catch (e) { /* 刷新失败则用现有 token */ }
895	
896	    try {
897	        const peerPort = peer.ws_port || 50002;
898	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
899	        const ws = new WebSocket(wsUrl);
900	
901	        ws.onopen = () => {
902	            // 发送连接请求，带上自己的 token 给对方后端验证
903	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
904	            ws.send(JSON.stringify({
905	                type: 'connect_request',
906	                uuid: myInfo.uuid,
907	                name: myInfo.name,
908	                token: myInfo.token,
909	                ip: myInfo.ip,
910	                ws_port: myInfo.ws_port,
911	            }));
912	        };
913	
914	        ws.onmessage = (e) => {
915	            const msg = JSON.parse(e.data);
916	            if (msg.type === 'connect_accepted') {
917	                activeChats.set(uuid, ws);
918	                connectedPeers.add(uuid);
919	                markConnected(uuid);
920	                setupPeerMessageHandler(uuid, ws);
921	                addSystemMessage(uuid, '连接已建立');
922	                updateChatHeaderStatus();
923	                renderOnlineList();
924	                renderContactsList();
