926	                controlWs.send(JSON.stringify({
927	                    type: 'save_contact',
928	                    uuid: uuid,
929	                    name: name,
930	                    ip: ip,
931	                    ws_port: peer.ws_port || 50002,
932	                }));
933	            } else if (msg.type === 'connect_rejected') {
934	                ws.close();
935	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
936	                addSystemMessage(uuid, reason);
937	                showToast(reason);
938	            }
939	        };
940	
941	        ws.onclose = () => {
942	            activeChats.delete(uuid);
943	            connectedPeers.delete(uuid);
944	            markDisconnected(uuid);
945	            // 中止与该对端的所有进行中文件上传（接收方断开时也要停止发送）
946	            abortTransfersForPeer(uuid);
947	            renderOnlineList();
948	            renderContactsList();
949	            if (currentChat === uuid) {
950	                addSystemMessage(uuid, '连接已断开');
951	                updateChatHeaderStatus();
952	            }
953	        };
954	
955	        ws.onerror = () => {
956	            activeChats.delete(uuid);
957	            markDisconnected(uuid);
958	            addSystemMessage(uuid, '连接失败，请检查网络');
959	            showToast('连接失败');
960	            ws.close();
961	        };
962	
963	    } catch (e) {
964	        addSystemMessage(uuid, `连接失败: ${e.message}`);
965	    }
966	}
