1100	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
1101	function setupPeerMessageHandler(uuid, ws) {
1102	    ws.onmessage = (e) => {
1103	        const msg = JSON.parse(e.data);
1104	        if (msg.type === 'chat') {
1105	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
1106	            handleDirectChatMessage(uuid, msg);
1107	        } else if (msg.type === 'file_request') {
1108	            // 对端后端通过 chat WS 发来的文件请求（HTTP relay 失败的 fallback）
1109	            // 先在自己后端注册 transfer，再弹窗确认
1110	            controlWs.send(JSON.stringify({
1111	                type: 'register_transfer',
1112	                transfer_id: msg.transfer_id,
1113	                file_name: msg.file_name,
1114	                file_size: msg.file_size,
1115	                chunk_size: msg.chunk_size,
1116	                total_chunks: msg.total_chunks,
1117	                from_uuid: uuid,
1118	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1119	            }));
1120	            // 用 from_uuid（chat WS 的对端 uuid）触发弹窗
1121	            showFileRequestModal({
1122	                transfer_id: msg.transfer_id,
1123	                file_name: msg.file_name,
1124	                file_size: msg.file_size,
1125	                from_uuid: uuid,
1126	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1127	            });
1128	        } else if (msg.type === 'file_response') {
1129	            // 对方对我方文件请求的响应
1130	            handleFileRequestResponse(msg);
1131	        } else if (msg.type === 'file_cancel') {
1132	            // 对方取消了传输
