1607	async function startChunkUpload(transferId) {
1608	    const t = pendingFileTransfers[transferId];
1609	    if (!t) return;
1610	
1611	    const fileMsg = findFileMsgByTransferId(transferId);
1612	    if (fileMsg) {
1613	        fileMsg.status = 'uploading';
1614	        saveFileMessage(t.uuid, fileMsg);
1615	        if (currentChat === t.uuid) renderMessages(t.uuid);
1616	    }
1617	
1618	    const peer = onlinePeers.get(t.uuid);
1619	    if (!peer) {
1620	        showToast('对方不在线，无法发送文件');
1621	        if (fileMsg) {
1622	            fileMsg.status = 'failed';
1623	            saveFileMessage(t.uuid, fileMsg);
1624	            if (currentChat === t.uuid) renderMessages(t.uuid);
1625	        }
1626	        delete pendingFileTransfers[transferId];
1627	        return;
1628	    }
1629	
1630	    const file = t.file;
1631	    const CHUNK_SIZE = t.CHUNK_SIZE;
1632	    const totalChunks = t.totalChunks;
1633	    const peerPort = peer.ws_port || 50002;
1634	
1635	    for (let i = t.currentChunk; i < totalChunks; i++) {
1636	        // 检查连接是否被中断（断开连接 / 对方下线）
1637	        if (t.aborted) {
1638	            if (fileMsg) {
1639	                fileMsg.status = 'cancelled';
1640	                saveFileMessage(t.uuid, fileMsg);
1641	                if (currentChat === t.uuid) renderMessages(t.uuid);
1642	            }
1643	            return; // 连接中断，中止上传
1644	        }
1645	
1646	        const start = i * CHUNK_SIZE;
1647	        const end = Math.min(start + CHUNK_SIZE, file.size);
1648	        const blob = file.slice(start, end);
1649	        const dataB64 = await readAsBase64(blob);
1650	
1651	        let retries = 0;
1652	        let success = false;
1653	
1654	        while (retries < 3 && !success) {
1655	            try {
1656	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1657	                    method: 'POST',
1658	                    headers: { 'Content-Type': 'application/json' },
1659	                    body: JSON.stringify({
1660	                        transfer_id: transferId,
1661	                        chunk_index: i,
1662	                        data: dataB64,
1663	                    }),
1664	                });
1665	                if (resp.ok) {
1666	                    success = true;
1667	                    t.currentChunk = i + 1;
1668	                    // 更新进度条
1669	                    if (fileMsg) {
1670	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1671	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1672	                    }
1673	                } else {
1674	                    retries++;
1675	                }
1676	            } catch (e) {
1677	                retries++;
1678	            }
1679	        }
1680	
1681	        if (!success) {
1682	            t.failed = true;
1683	            if (fileMsg) {
1684	                fileMsg.status = 'failed';
1685	                saveFileMessage(t.uuid, fileMsg);
1686	                if (currentChat === t.uuid) renderMessages(t.uuid);
1687	            }
1688	            return; // 传输中断（保留 t 以便续传）
1689	        }
1690	    }
1691	
1692	    // 所有分片发送完毕 → 通知对方合并
1693	    try {
1694	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1695	            method: 'POST',
1696	            headers: { 'Content-Type': 'application/json' },
1697	            body: JSON.stringify({ transfer_id: transferId }),
1698	        });
1699	        if (fileMsg) {
1700	            fileMsg.status = 'complete';
1701	            fileMsg.progress = 100;
1702	            saveFileMessage(t.uuid, fileMsg);
1703	            if (currentChat === t.uuid) renderMessages(t.uuid);
1704	        }
1705	    } catch (e) {
1706	        if (fileMsg) {
1707	            fileMsg.status = 'failed';
1708	            saveFileMessage(t.uuid, fileMsg);
1709	            if (currentChat === t.uuid) renderMessages(t.uuid);
1710	        }
1711	    }
1712	
1713	    delete pendingFileTransfers[transferId];
1714	}
