1716	/**
1717	 * 重新发送（续传）失败的文件。查询接收方已收分片，只补发缺失部分。
1718	 * @param {string} transferId - 原传输 ID
1719	 */
1720	async function retryFileTransfer(transferId) {
1721	    // 1. 检查是否有文件数据（页面刷新后 File 对象会丢失）
1722	    const t = pendingFileTransfers[transferId];
1723	    if (!t || !t.file) {
1724	        showToast('无法续传：文件数据已丢失，请重新选择文件发送');
1725	        return;
1726	    }
1727	
1728	    // 2. 检查对方是否在线
1729	    const peer = onlinePeers.get(t.uuid);
1730	    if (!peer) {
1731	        showToast('对方不在线，无法续传');
1732	        return;
1733	    }
1734	
1735	    // 2.5 必须有已建立的 chat WS 连接才能续传（否则 file_request 无法送达）
1736	    const chatWs = activeChats.get(t.uuid);
1737	    const isConnected = (chatWs && chatWs.readyState === WebSocket.OPEN) || connectedPeers.has(t.uuid);
1738	    if (!isConnected) {
1739	        showToast('请先点击"连接"建立聊天连接，再重新发送文件');
1740	        return;
1741	    }
1742	
1743	    // 3. 查询接收方已收到的分片数
1744	    let receivedChunks = 0;
1745	    const peerPort = peer.ws_port || 50002;
1746	    try {
1747	        const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/status/${transferId}`);
1748	        if (resp.ok) {
1749	            const status = await resp.json();
1750	            receivedChunks = status.received_chunks_count || 0;
1751	        }
1752	    } catch (e) {
1753	        // 进度丢失，从头开始
1754	        console.log('[Retry] 无法获取进度，从头开始:', e.message);
1755	    }
1756	
1757	    // 4. 更新传输状态 — 从已收到的下一片开始
1758	    t.currentChunk = receivedChunks;
1759	    t.started = false;
1760	    t.failed = false;
1761	    t.aborted = false;
1762	
1763	    // 5. 更新文件消息气泡
1764	    const fileMsg = findFileMsgByTransferId(transferId);
1765	    if (fileMsg) {
1766	        fileMsg.status = 'waiting';
1767	        fileMsg.progress = Math.round(receivedChunks / t.totalChunks * 100);
1768	        saveFileMessage(t.uuid, fileMsg);
1769	        if (currentChat === t.uuid) renderMessages(t.uuid);
1770	    }
1771	
1772	    // 6. 重新发送 file_request（带 resume 标记，接收方会跳过确认直接接受）
1773	    const fileRequestMsg = {
1774	        transfer_id: transferId,
1775	        file_name: t.file.name,
1776	        file_size: t.file.size,
1777	        chunk_size: t.CHUNK_SIZE,
1778	        total_chunks: t.totalChunks,
1779	        resume: true,
1780	    };
1781	
1782	    const ws = activeChats.get(t.uuid);
1783	    if (ws && ws.readyState === WebSocket.OPEN) {
1784	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
1785	    } else {
1786	        // 回退路径：通过 control WS 转发
1787	        controlWs.send(JSON.stringify({
1788	            type: 'file_request',
1789	            to_uuid: t.uuid,
1790	            ...fileRequestMsg,
1791	        }));
1792	    }
1793	}
