1795	function readAsBase64(blob) {
1796	    return new Promise((resolve) => {
1797	        const reader = new FileReader();
1798	        reader.onloadend = () => {
1799	            const result = reader.result;
1800	            // 去掉 "data:...;base64," 前缀
1801	            const b64 = result.split(',')[1] || result;
1802	            resolve(b64);
1803	        };
1804	        reader.readAsDataURL(blob);
1805	    });
1806	}
