1846	                msg_id: msgId,
1847	                timestamp: new Date().toISOString(),
1848	                file_name: msg.file_name,
1849	                file_size: msg.file_size,
1850	                transfer_id: msg.transfer_id,
1851	                direction: 'receive',
1852	                status: 'downloading',
1853	                progress: 0,
1854	            };
1855	            contact.messages.push(fileMsg);
1856	            saveFileMessage(uuid, fileMsg);
