1877	// ===== 文件传输辅助函数 =====
1878	
1879	/** 根据 transfer_id 在所有联系人的消息中查找文件消息 */
1880	function findFileMsgByTransferId(transferId) {
1881	    for (const [uuid, contact] of contacts) {
1882	        if (contact.messages) {
1883	            // 从后往前找（文件消息通常在末尾）
1884	            for (let i = contact.messages.length - 1; i >= 0; i--) {
1885	                if (contact.messages[i].transfer_id === transferId) {
1886	                    return contact.messages[i];
1887	                }
1888	            }
1889	        }
1890	    }
1891	    return null;
1892	}
