1894	/** 持久化文件消息到后端 contacts.json（里程碑状态变化时调用，避免每次进度更新都写盘） */
1895	function saveFileMessage(peerUuid, fileMsg) {
1896	    if (!peerUuid || !fileMsg || !fileMsg.msg_id) return;
1897	    controlWs.send(JSON.stringify({
1898	        type: 'save_message',
1899	        msg_type: 'file',
1900	        peer_uuid: peerUuid,
1901	        sender: fileMsg.from === 'me' ? 'me' : peerUuid,
1902	        content: '',
1903	        msg_id: fileMsg.msg_id,
1904	        file_name: fileMsg.file_name,
1905	        file_size: fileMsg.file_size,
1906	        transfer_id: fileMsg.transfer_id,
1907	        status: fileMsg.status,
1908	        progress: fileMsg.progress || 0,
1909	    }));
1910	}
